        var bp = BOTP[i];
        if (now >= b.next) {
          b.next = now + 420 + Math.random() * 400;
          var bx = b.cell % GW, by = (b.cell / GW) | 0, tx = b.tgt % GW, ty = (b.tgt / GW) | 0;
          if (b.cell === b.tgt || Math.random() < 0.04) { var nx = Math.max(0, Math.min(GW - 1, bx + Math.round((Math.random() - 0.5) * 14 * SC))), ny = Math.max(0, Math.min(GH - 1, by + Math.round((Math.random() - 0.5) * 14 * SC))); if (grid[ny * GW + nx]) b.tgt = ny * GW + nx; if (Math.random() < 0.12) b.tgt = SEAT[1 + Math.floor(Math.random() * N)]; tx = b.tgt % GW; ty = (b.tgt / GW) | 0; }
          var sx = Math.sign(tx - bx), sy = Math.sign(ty - by), cand = [[sx, sy], [sx, 0], [0, sy]];
          for (var k = 0; k < cand.length; k++) { var ncx = bx + cand[k][0], ncy = by + cand[k][1], ni = ncy * GW + ncx; if ((cand[k][0] || cand[k][1]) && ncx >= 0 && ncy >= 0 && ncx < GW && ncy < GH && grid[ni] && !(RIV[ni] && !ROAD[ni])) { b.cell = ni; moved = true; break; } }
          if (b.cell !== (b.lastCell || -1)) { b.lastCell = b.cell; }
          lsSet(K + 'b:b' + i, JSON.stringify({ team: bp.t, cell: b.cell, t: now, cls: bp.c, name: bp.n, st: bp.st, tr: BTR[i] }));
        }
